package android.media;public class AudioTrack{public static final int MODE_STREAM=1,PLAYSTATE_PLAYING=3,WRITE_BLOCKING=0;public static int getMinBufferSize(int a,int b,int c){return 16384;}private int frames;public void play(){}public void pause(){}public void flush(){frames=0;}public int getPlaybackHeadPosition(){return frames;}public int getPlayState(){return 3;}public int write(short[] s,int a,int b,int c){frames+=b/2;return b;}public void release(){}public static class Builder{public Builder setAudioAttributes(AudioAttributes a){return this;}public Builder setAudioFormat(AudioFormat a){return this;}public Builder setBufferSizeInBytes(int i){return this;}public Builder setTransferMode(int i){return this;}public AudioTrack build(){return new AudioTrack();}}}